"""Route registry for REST v2 auto-generated file endpoints."""

from __future__ import annotations

from typing import TYPE_CHECKING

from ai.backend.manager.api.rest.middleware.auth import auth_required
from ai.backend.manager.api.rest.routing import RouteRegistry

from .handler import V2AutoGeneratedFileHandler

if TYPE_CHECKING:
    from ai.backend.manager.api.rest.types import RouteDeps


def register_v2_auto_generated_file_routes(
    handler: V2AutoGeneratedFileHandler,
    route_deps: RouteDeps,
) -> RouteRegistry:
    """Register all REST v2 auto-generated file routes and return the sub-registry."""
    registry = RouteRegistry.create("auto-generated-files", route_deps.cors_options)

    registry.add("POST", "", handler.create, middlewares=[auth_required])
    registry.add("POST", "/scoped/search", handler.scoped_search, middlewares=[auth_required])
    registry.add("POST", "/my/search", handler.my_search, middlewares=[auth_required])
    registry.add(
        "POST",
        "/{auto_generated_file_id}/switch-default",
        handler.switch_default,
        middlewares=[auth_required],
    )
    registry.add("DELETE", "/{auto_generated_file_id}", handler.purge, middlewares=[auth_required])

    return registry
